// Raw request body bytes, captured by express.json()'s `verify` hook in
// app.ts. Needed for webhook signature verification (Phase 4) — HMAC
// signatures are computed over the exact bytes the provider sent, and
// re-serialising the parsed JSON body can differ from that byte-for-byte.
//
// correlationId: a per-HTTP-request id generated by
// middlewares/requestId.ts, mounted early in app.ts ahead of every route,
// and echoed back as the X-Correlation-Id response header — gives every
// request an inspectable, client-visible id for tying it to server logs
// (and, separately, to whatever domain event(s) it goes on to publish via
// @aee/events's own per-event newCorrelationId()).
declare global {
  namespace Express {
    interface Request {
      rawBody?: Buffer;
      correlationId?: string;
    }
  }
}

export {};
